import Config

# Runtime configuration — evaluated when the release boots, not at compile time.
# config/prod.exs only runs at `mix release` build time, so DATABASE_URL etc.
# set by Salt/launchd on the deploy target were never actually read.

if config_env() == :prod do
  # Load bot-specific config from file (generated by Salt at deployment time)
  # This avoids the macOS launchd environment variable pass-through limitation.
  # Never write config_data anywhere: it holds the DB password, the Erlang cookie
  # and the sealed-request key. (A debug dump of it to a world-readable
  # /tmp/runtime-exs-debug.log was removed 2026-11-19.)
  config_data = BotArmyLibraryRuntime.ConfigLoader.load_config()

  Application.put_env(:bot_army_library_runtime, :config_data, config_data)

  # Seal the words sent to the llm bot (reflections, letters). The key itself is read by
  # BotArmyCompanion.Sealed from LLM_SEALED_KEYS; this only says whether sealing is required.
  config :bot_army_companion, :reflection_answer,
    seal: BotArmyLibraryRuntime.ConfigLoader.get("COMPANION_SEAL_LLM") == "true"

  config :bot_army_companion, BotArmyCompanion.Repo,
    database:
      BotArmyLibraryRuntime.ConfigLoader.get("BOT_ARMY_COMPANION_DB_NAME", "ergon_companion"),
    hostname: BotArmyLibraryRuntime.ConfigLoader.get("BOT_ARMY_COMPANION_DB_HOST", "localhost"),
    port:
      String.to_integer(
        BotArmyLibraryRuntime.ConfigLoader.get("BOT_ARMY_COMPANION_DB_PORT", "30006")
      ),
    username: BotArmyLibraryRuntime.ConfigLoader.get("BOT_ARMY_COMPANION_DB_USER", "postgres"),
    password:
      BotArmyLibraryRuntime.ConfigLoader.get("BOT_ARMY_COMPANION_DB_PASSWORD", "postgres"),
    pool_size:
      String.to_integer(BotArmyLibraryRuntime.ConfigLoader.get("POSTGRES_POOL_SIZE", "10")),
    ssl: BotArmyLibraryRuntime.ConfigLoader.get("DATABASE_SSL") == "true",
    socket_options:
      if(BotArmyLibraryRuntime.ConfigLoader.get("DATABASE_SOCKET_TIMEOUT"),
        do: [
          connect_timeout:
            String.to_integer(BotArmyLibraryRuntime.ConfigLoader.get("DATABASE_SOCKET_TIMEOUT"))
        ],
        else: []
      )

  # NATS configuration for bot_army_runtime — the library starts NATS.Connection
  # with empty opts and its fail-safe default is the DEV broker (4223). Without
  # this block companion joins the wrong bus: subscriptions, heartbeats and
  # presence all live on 4223 while the fleet runs on 4222. Same pattern as
  # bot_army_llm / bot_army_sre / bot_army_deploy_pipeline runtime.exs.
  nats_host = BotArmyLibraryRuntime.ConfigLoader.get("NATS_HOST", "localhost")

  nats_port =
    BotArmyLibraryRuntime.ConfigLoader.get("NATS_PORT", "4222") |> String.to_integer()

  config :bot_army_library_runtime, :nats,
    servers: [{nats_host, nats_port}],
    ping_interval: 30_000,
    max_reconnect_attempts: 10,
    reconnect_delay_ms: 1000

  # The party name this bot answers to. Deployable without a code change because it is
  # an identity the fleet hands out (pillar/env), not a decision this bot makes.
  config :bot_army_companion,
    bot_id: BotArmyLibraryRuntime.ConfigLoader.get("BOT_ID", "companion_bot")

  config :logger,
    level: String.to_atom(BotArmyLibraryRuntime.ConfigLoader.get("LOG_LEVEL", "info"))
end
